@import url('https://fonts.googleapis.com/css2?family=Fjalla+One&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* NBA DNA — league blue and red on white, gold trophy accents, broadcast bold */
.theme-nba-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.973 0 0);
  --surface-2: oklch(0.928 0 0);
  --fg: oklch(0.173 0 0);
  --fg-muted: oklch(0.468 0 0);
  --accent: oklch(0.396 0.128 261.9);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.530 0.207 22.3);
  --line: oklch(0.891 0 0);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.530 0.207 22.3);
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.75rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Fjalla One", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.08em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-nba-dna h1,
.theme-nba-dna h2,
.theme-nba-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-nba-dna { --font-ui: var(--font-display); }
.theme-nba-dna h1, .theme-nba-dna h2 { text-transform: uppercase; }
.theme-nba-dna h1::after { content: ""; display: block; height: 4px; width: 6rem; margin-top: 0.6rem; background: linear-gradient(90deg, var(--accent) 0 50%, var(--accent-2) 50% 100%); }
.theme-nba-dna button { text-transform: uppercase; letter-spacing: 0.08em; }

/* depth */
.theme-nba-dna ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-nba-dna thead th { font-family: var(--font-display); text-transform: uppercase; letter-spacing: 0.08em; font-weight: 400; background: var(--accent); color: var(--accent-fg); }
.theme-nba-dna td { border-bottom: 1px solid var(--line); font-variant-numeric: tabular-nums; }
.theme-nba-dna tbody tr:nth-child(even) { background: var(--surface); }
.theme-nba-dna tbody tr:hover { background: color-mix(in oklab, var(--accent) 10%, transparent); box-shadow: inset 3px 0 0 var(--accent-2); }
.theme-nba-dna a { color: var(--accent); font-weight: 600; text-decoration: none; border-bottom: 2px solid oklch(0.780 0.130 85.0); }
.theme-nba-dna a:hover { color: var(--accent-2); border-bottom-color: var(--accent-2); }
.theme-nba-dna input, .theme-nba-dna select, .theme-nba-dna textarea { border: 1px solid var(--line); border-radius: var(--radius); background: var(--bg); }
.theme-nba-dna input:focus-visible, .theme-nba-dna select:focus-visible, .theme-nba-dna textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px color-mix(in oklab, var(--accent) 30%, transparent); }
.theme-nba-dna kbd { font-family: var(--font-display); background: var(--fg); color: var(--bg); border-radius: var(--radius-sm); padding: 0.1em 0.5em; font-variant-numeric: tabular-nums; }
.theme-nba-dna .label-caps { font-family: var(--font-display); color: var(--accent); }
.theme-nba-dna .themed-border { border-top: 4px solid; border-image: linear-gradient(90deg, var(--accent) 0 50%, var(--accent-2) 50% 100%) 1; }
.theme-nba-dna button { transition: box-shadow 120ms ease, transform 120ms ease; }
.theme-nba-dna button:hover { box-shadow: 0 4px 0 oklch(0.780 0.130 85.0); transform: translateY(-2px); }
.theme-nba-dna button:active { box-shadow: none; transform: translateY(0); }
.theme-nba-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-nba-dna ::-webkit-scrollbar-track { background: var(--surface); }
.theme-nba-dna ::-webkit-scrollbar-thumb { background: var(--accent); border-radius: 9999px; }
.theme-nba-dna ::-webkit-scrollbar-thumb:hover { background: var(--accent-2); }

/* alt mode: city edition night — arena black, gold trophy trim */
.theme-nba-dna.alt-mode {
  --bg: oklch(0.145 0.000 0.0);
  --surface: oklch(0.185 0.000 0.0);
  --surface-2: oklch(0.225 0.000 0.0);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --accent: oklch(0.62 0.128 261.9);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.660 0.207 22.3);
}
.theme-nba-dna.alt-mode a { color: oklch(0.820 0.130 85.0); border-bottom-color: oklch(0.820 0.130 85.0 / 50%); }
.theme-nba-dna.alt-mode a:hover { color: oklch(0.90 0.13 85.0); border-bottom-color: oklch(0.90 0.13 85.0); }
.theme-nba-dna.alt-mode .label-caps { color: oklch(0.820 0.130 85.0); }
.theme-nba-dna.alt-mode input, .theme-nba-dna.alt-mode select, .theme-nba-dna.alt-mode textarea { background: var(--surface); }
.theme-nba-dna.alt-mode kbd { background: oklch(0.820 0.130 85.0); color: oklch(0.15 0 0); }
.theme-nba-dna.alt-mode button:hover { box-shadow: 0 4px 0 oklch(0.820 0.130 85.0); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
